        lcp[i][j]=lcp[j][i]=k;base+=k;
    }
    for(int i=0;i<n;i++){
        int length=s[i].size();
        vector<int>loss(length,0);
        vector<array<int,26>>gain(length);
        for(int j=0;j<n;j++)if(i!=j){
            int k=lcp[i][j];
            for(int p=0;p<k;p++)loss[p]+=k-p;
            if(k<(int)min(s[i].size(),s[j].size())){
                int end=k+1;
                while(end<(int)min(s[i].size(),s[j].size())&&s[i][end]==s[j][end])++end;
                gain[k][s[j][k]-'a']+=end-k;
            }
        }
        for(int p=0;p<length;p++)for(int c=0;c<26;c++)if(c!=s[i][p]-'a')
            best=max(best,1LL*gain[p][c]-loss[p]);
    }
    cout<<base+best<<"\n";
}
```

### 易错点

不能只计算新增加的公共前缀，修改也可能破坏其他数对原有的长前缀。某串结束不是可修改的失配字符。总分仅统计无序对一次，但分析一个被修改字符串时要考虑它与所有其他串。

